// pubspec.yaml:
//   cached_network_image: ^3.3.1
//   flutter_cache_manager: ^3.3.1
import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter_cache_manager/flutter_cache_manager.dart';

// ────── Simple usage in a feed ──────
CachedNetworkImage(
  imageUrl: item.photoUrl,
  fit: BoxFit.cover,
  memCacheWidth: 400,           // decode at 400 px width — HUGE perf win
  fadeInDuration: const Duration(milliseconds: 200),
  placeholder: (_, __) => const ColoredBox(color: Color(0xFFEEEEEE)),
  errorWidget: (_, __, ___) => const Icon(Icons.broken_image),
);

// ────── With download progress ──────
CachedNetworkImage(
  imageUrl: hero.url,
  progressIndicatorBuilder: (_, __, dl) => Center(
    child: CircularProgressIndicator(value: dl.progress),
  ),
);

// ────── DecorationImage via provider ──────
Container(
  decoration: BoxDecoration(
    image: DecorationImage(
      image: CachedNetworkImageProvider(user.avatarUrl),
      fit: BoxFit.cover,
    ),
  ),
);

// ────── Custom cache manager — TTL + max size ──────
class FeedCacheManager extends CacheManager {
  static const key = 'feedCache';
  FeedCacheManager() : super(Config(
    key,
    stalePeriod: const Duration(days: 7),
    maxNrOfCacheObjects: 500,
  ));
}

CachedNetworkImage(
  imageUrl: item.photoUrl,
  cacheManager: FeedCacheManager(),
);

// ────── Preload upcoming images ──────
for (final url in upcomingUrls) {
  precacheImage(CachedNetworkImageProvider(url), context);
}

// ────── Evict a stale URL ──────
await DefaultCacheManager().removeFile(oldUrl);
CachedNetworkImage.evictFromCache(oldUrl);   // memory too

// ────── Wipe everything (logout) ──────
await DefaultCacheManager().emptyCache();
imageCache.clear();
imageCache.clearLiveImages();
